SELECT id, doc_type, title, content::text AS content
FROM invoice
WHERE id = #{id}
    AND user_id = #{userId}
    AND deleted = FALSE
FOR SHARE

SELECT COALESCE(MAX(RIGHT(doc_no, 4)::integer), 0)
FROM invoice
WHERE user_id = #{userId}
    AND doc_type = #{docType}
    AND doc_no ~ ('^' || #{prefix} || '[0-9]{4}$')
